local IdConcatTable = {0, "_", 0}

local function IdConcat(left, right)
    IdConcatTable[1] = left  or 0
    IdConcatTable[3] = right or 0
    return table.concat(IdConcatTable)
end

local function GetTableFile(idSetting, suffix)
    local tableName = string.format("%s%s", idSetting, string.isEmpty(suffix) and "IDGroup" or suffix)
    local tableFile = SettingMgr:GetInstance():Get(tableName)
    return tableFile
end

local function GetIdGroupData(idSetting, key, throwError, suffix)
    local tableFile = GetTableFile(idSetting, suffix)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(checkString(key), throwError)
    return row
end

local function GetIdGroupRowData(idSetting, key, rowName, throwError, splitFlag, suffix)
    rowName = rowName or "ids"
    ---@type TableML.TableFileRow
    local row = GetIdGroupData(idSetting, key, throwError, suffix)
    if not isNull(row) then
        local ids = parse_strings(row:Get(rowName), splitFlag or ';')
        return ids
    end
    return nil
end

