---GetAllScreenVo
---@return ScreenVo[]
function CardConfMgr:GetAllScreenVo(filterType)
    if isNull(filterType) then
        filterType = Constants.UIFilterType.Card
    end
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type table<string, TableML.TableFileRow>
    local tableFile = settingMgr:Get(AutoIds.IdSetting47)
    local t = {}
    local ScreenVo = import('Game.Setting.Vo.ScreenVo')
    local vo = nil
    for _, row in pairs(tableFile) do
        local class = checkNumber(row:Get("class"))
        if class == filterType then
            vo = ScreenVo.New()
            vo:FillVo(row)
            table.insert(t, vo)
        end
    end
    return t
end

