function CardConfMgr:GetMaxFinalSkillLv()
    if self._maxFinalSkillLv == nil then
        self:InitMaxFinalSkillLv()
    end
    return self._maxFinalSkillLv
    
end
function CardConfMgr:InitMaxFinalSkillLv()
    local setting = CfUtils.GetCfTable(AutoIds.IdSetting1202)
    local allRow = setting:GetAll()
    local parse_number = parse_number
    local lv = 0
    local rare
    for i, row in pairs(allRow) do
        local newRare = parse_number(row, "rare")
        if rare == nil or newRare == rare then
            rare = newRare
            lv = lv + 1
        else
            break
        end

    end
    self._maxFinalSkillLv = lv

end

function CardConfMgr:GetMaxBuffSkillLv(cardId)
    return self:InitMaxBuffSkillLv(cardId)
end
function CardConfMgr:InitMaxBuffSkillLv(cardId)
    local maxBuffSkillLv  = nil

    local starIds = self:GetCardStarIds(cardId)
    if starIds == nil then
        return
    end
    ---@type CardStarVo
    local vo
    for i = #starIds, 1, -1 do
        local starId = starIds[i]
        vo = self:GetCardStarVo(starId)
        if maxBuffSkillLv == nil and vo.passiveLevel > 0 then
            maxBuffSkillLv = vo.passiveLevel
        end
        if maxBuffSkillLv then
            break
        end
    end
    
    
    return maxBuffSkillLv
    
end


