    return setting:Get(key)
end

---GetEquipExpByLevelId
---根据等级获取装备的当前的经验信息
function CardConfMgr:GetEquipExpByLevelId(levelUpType, quality, level)
    if level <= 1 then
        return {
            levelId = level,
            exp = 0,
            totalExp = 0
        }
    end
    local maxLevel = self:GetEquipMaxLevelByQuality(quality)
    if level > maxLevel then
        level = maxLevel
    end

    local levelId = IdConcat(levelUpType, level)
    local settingKey = AutoIds.IdSetting100
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    local tableFile = settingMgr:Get(string.format("%s%s", settingKey, "IDGroup"))
    local row = tableFile:GetByPrimaryKey(levelId)
    local exp = parseUtils.ParseInt(row, "exp")
    local totalExp = parseUtils.ParseInt(row, "totalExp")

    return {
        levelId = levelId,
        exp = exp,
        totalExp = totalExp
    }
end

function CardConfMgr:GetEquipMaxLevelByQuality(quality_)
    if self.equipMaxLevel == nil then
        self.equipMaxLevel = {}
        ---@type SettingMgr
        local settingMgr = SettingMgr:GetInstance()
        local tableFile = settingMgr:Get(AutoIds.IdSetting98)
        for _, row in pairs(tableFile) do
            local quality = parseUtils.ParseInt(row, "qualityLv")
            local level = parseUtils.ParseInt(row, "lvMax")
            self.equipMaxLevel[quality] = level
        end
    end
    return checkNumber(self.equipMaxLevel[checkNumber(quality_)])
end

