---GetEquipAttrAdditionValue
---获取属性加成
---@param equipAttrType number
---@param quality number
---@param level number
---@param attrTypeId Constants.AttrTypeId
---@param addType number 加成类别是加常量还是加百分比的值
---@return number
function CardConfMgr:GetEquipAttrAdditionValue(equipAttrType, quality, level, attrTypeId, addType)
    local result = 0
    local vo = self:GetEquipAttrVoById(equipAttrType)
    local additionVo = self:GetBasicAttrAdditionById(vo.attrAdditionId)
    if additionVo.attrId == checkNumber(attrTypeId) then
        if additionVo.attAddType == checkNumber(addType) then
            result = result + vo.attrNum[quality].baseValue + vo.attrNum[quality].growValue * level
        end
    end
    return result
end

---CalcEquipAttrNum
---获取 equip 属性值
---@param level number
---@param attrTypeId Constants.AttrTypeId
---@param quality number
function CardConfMgr:CalcEquipAttrNum(level, attrTypeId, quality)
    local attrVo = self:GetEquipAttrVoById(attrTypeId)
    local attrNumVo = attrVo.attrNum[checkNumber(quality)]
    -- 基础属性 + 每级成长
    return attrNumVo.baseValue + checkNumber(level) * attrNumVo.growValue
end

