---主角经验相关--
function CardConfMgr:GetPlayerMaxLevel()
    if self.playerMaxLevel then
        return self.playerMaxLevel
    end
    local maxLevel = 1;
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = settingMgr:Get(AutoIds.IdSetting38)
    for i, row in pairs(tableFile) do
        local curLevel = row:Get_int(row:Get("playerLevel"), "0");
        if curLevel > maxLevel then
            maxLevel = curLevel
        end
    end

    self.playerMaxLevel = maxLevel

    return maxLevel
end

---GetPlayerExpByLevelId
---获取等级对应的经验
---@param levelId number
---@return table
function CardConfMgr:GetPlayerExpByLevelId(levelId, oldLevelId)
    local maxLevel = self:GetPlayerMaxLevel()
    if levelId > maxLevel then
        levelId = maxLevel
    end
    if levelId < 1 then
        levelId = 1
    end
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = settingMgr:Get(AutoIds.IdSetting38)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(levelId)
    local exp = row:Get_int(row:Get("exp"), "0")
    local totalExp = 0
    for i, tRow in pairs(tableFile) do
        totalExp = totalExp + parseUtils.ParseInt(tRow, "exp")
        local curLevel = tRow:GetPrimaryKey()
        if checkInt(curLevel) == checkInt(levelId) then
            break
        end
    end

    local rewards = self:GetLevelUpRewards(oldLevelId, levelId)
    return {
        levelId = levelId,
        exp = exp,
        totalExp = totalExp,
        rewards = rewards,
        hpMax = checkNumber(row:Get("hpMax"))
    }
end

--获取升级奖励
function CardConfMgr:GetLevelUpRewards(oldLevelId, newLevelId)
    oldLevelId = checkNumber(oldLevelId)
    newLevelId = checkNumber(newLevelId)

    local t = {}
    if newLevelId <= oldLevelId then
        return t
    end
    local maxLevel = self:GetPlayerMaxLevel()
    if newLevelId > maxLevel then
        return t
    end
    local minLevel = 1
    if oldLevelId < minLevel then
        return t
    end

    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = settingMgr:Get(AutoIds.IdSetting38)

    --当前等级的不能进来
    for i = oldLevelId + 1, newLevelId do
        local row = tableFile:GetByPrimaryKey(i)
        if row then
            local rewards = row:Get("upRewards")
            local rewardNums = row:Get("upRewardsNum")
            if rewards and rewardNums then
                rewards = CfUtils.Split(rewards)
                rewardNums = CfUtils.Split(rewardNums)
                if rewards and rewardNums then
                    for i = 1, #rewards do
                        local r = {
                            goodsId = rewards[i],
                            num = checkNumber(rewardNums[i])
                        }
                        table.insert(t, r)
                    end
                end
            end
        end
    end
    return t
end

