    local vo = self:GetBaseMonstVo(refId)
    if vo then
        local skinVo = self:GetCardSkinBySkinId(vo.skinId)
        if skinVo then
            return skinVo.buffHead
        end
    end
    return nil
end

---GetMonstHeadBg 获取怪物小头像背景
---@param refId number
function CardConfMgr:GetMonstHeadBg(refId)
    if checkNumber(refId) == 0 then
        return nil
    end
    local vo = self:GetBaseMonstVo(refId)
    if not vo then
        return nil
    end
    --人形怪转一层
    if checkNumber(vo.role) > 0 then
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(vo.mode)
        if cardVo then
            return CfUtils.GetRareBgRare(cardVo.rare, 2)
        end
    end
    return CardUtils.GetMonsterRareBgByMonsterClass(vo.monsterClass)
end

