---GetCardPosByCardId
---获取卡牌坐标信息
---@param refId number
---@return CardPositionVo
function CardConfMgr:GetCardPosByCardId(refId, skinId, isIgnoreError)
    if skinId == nil then
        return
    end
    local posInfo = nil
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = settingMgr:Get(AutoIds.IdSetting114)
    local row = tableFile:FindByPrimaryKey(skinId, false)
    if isNull(row) then
        row = tableFile:FindByPrimaryKey(refId, false)
    end
    if not isNull(row) then
        local vo = import('Game.Setting.Vo.CardPositionVo')
        posInfo = vo.New(row)
    elseif not isIgnoreError then
        printError("角色卡牌坐标表 未找到卡牌id %s", refId)
    end
    return posInfo
end


