---GetBasicAttrs
---取得所有属性定义表中的前n个属性信息列表
---@param attrNum number
---@return AttrDefinesVo[]
function CardConfMgr:GetBasicAttrs(attrNum)
    ---因属性修改，此处定死主属性先,取几个主属性
    ---@type AttrDefinesVo[]
    local basicAttrVos = self:GetBasicAttrVos()
    local maxAttrCount = #basicAttrVos
    if attrNum == nil or checkInt(attrNum) > maxAttrCount then
        return basicAttrVos
    end
    
    local attrs = {}
    for i = 1, attrNum do
        local vo = basicAttrVos[i]
        table.insert(attrs, vo)
    end
    return attrs
end

---GetBasicAttrVos
---基础属性数据列表
---@return AttrDefinesVo[]
function CardConfMgr:GetBasicAttrVos()
    if self._basicAttrs == nil then
        local attrVos = {}
        ---@type AttrDefinesVo[]
        local vos = CfUtils.GetCf(AutoIds.IdSetting46, "AttrDefinesVo", true)
        for k, v in ipairs(vos) do
            local order = v.order
            if order > 0 then
                table.insert(attrVos, v)
            end
        end
        table.sort(attrVos, function(a, b) return a.order < b.order end)
        self._basicAttrs = attrVos
    end
    return self._basicAttrs
end

