---WalkAllStarEffect
---获取所有 根据星级解锁的 角色大招被动表
---@param cardId number
---@field func fun(vo: CardFinalAndBuffSkillVo, index: number)
---@return CardFinalAndBuffSkillVo[]
function CardConfMgr:WalkAllStarEffect(cardId, func)
    local ids = self:GetCardStarIds(cardId)
    -- local ids = self:GetCardFinalAndBuffIds(cardId)
    if ids == nil then
        return
    end
    ---@type CardStarVo
    local vo
    for index, id in pairs(ids) do
        vo = self:GetCardStarVo(id)
        if vo.skillType == CardProgressionConstants.SkillType.Star then
            if func then
                if func(vo, index) then
                    break
                end
            end
        end
    end

