---GetFinalCapabilityValue
---@param cardId number 卡牌id
---@param skillType CardProgressionConstants.SkillType
---@param finalSkillLevel number 大招等级
function CardConfMgr:GetFinalCapabilityValue(cardId, skillType, finalSkillLevel)
    ---@type CardFinalAndBuffSkillVo
    local vo = self:GetCardFinalAndBuffSkillVo(cardId, skillType)
    if vo == nil then return 0 end
    local totalV          = 0
    local capabilityValue = vo.capabilityValue
    for i = 1, finalSkillLevel do
        totalV = totalV + checkNumber(capabilityValue[i])
    end
    return totalV
end

function CardConfMgr:GetBuffCapabilityValue(cardId, skillType, awakeningLevel)
    ---@type CardFinalAndBuffSkillVo
    local vo = self:GetCardFinalAndBuffSkillVo(cardId, skillType)
    if vo == nil then return 0 end
    local totalV          = 0
    local capabilityValue = vo.capabilityValue
    for i = 1, awakeningLevel do
        totalV = totalV + checkNumber(capabilityValue[i])
    end
    return totalV
end

