--- GetCardRare
--- 获取卡牌最大等级
---@param advanceLevel number 升阶等级
function CardConfMgr:GetCardRare(advanceLevel, initRare)
    initRare = initRare or Constants.RareType.R
    ---@type RoleAdvanceLevelLimitVo
    local advanceLevelLimitVo = self:GetRoleAdvanceLevelLimitVo(advanceLevel)
    if advanceLevelLimitVo then
        return math.max(advanceLevelLimitVo.rare, initRare)
