---GetCardExp
---获取卡牌当前等级的经验信息
---@param levelId number
---@param initRare number 卡牌稀有度
---@param maxLevel number 卡牌最大等级
function CardConfMgr:GetCardExp(levelId, initRare, maxLevel)
    --- 升级经验只和初始品质相关，配置每个等级初始R/SR/SSR的品质需要的经验值，升级所需经验只和初始品质挂钩
    levelId  = checkNumber(levelId)
    maxLevel = checkNumber(maxLevel)

    if maxLevel == 0 then
        printError("maxLevel 等于 0")
    end
    if levelId > maxLevel and maxLevel > 0 then
        levelId = maxLevel
    end

    if levelId <= 1 then
        return { levelId = levelId, exp = 0, totalExp = 0 }
    end

    local row = GetIdGroupData(AutoIds.IdSetting17, levelId, false)
    if isNull(row) then
        printError("卡牌升级经验表 未找到 %s", levelId)
        return { levelId = levelId, exp = 0, totalExp = 0 }
    end
    return {
        levelId  = levelId,
        exp      = parse_number(row, string.format("exp%s", initRare)),
        totalExp = parse_number(row, string.format("totalExp%s", initRare))
    }

end

