--- GetRoleCardSynergies
--- 取得卡牌id 所对应的 角色羁绊表 ids
---@param cardId number 卡牌id
function CardConfMgr:GetRoleCardSynergies(cardId)
    local ids = GetIdGroupRowData(AutoIds.IdSetting57, cardId, "ids", false, ";")
    if ids then
        --- 检查下卡牌表的 handbook是否打开
        local c = #ids
        for i = c, 1, -1 do
            local voId = ids[i]
            ---@type RoleCardSynergiesVo
            local vo = self:GetRoleCardSynergiesVo(voId)
            local relationCardId = vo.relationCard
            local cardVo = self:GetCardByRefId(relationCardId)
            if cardVo == nil or not cardVo.isHandbook then
                table.remove(ids, i)
            end
        end
    end
    -- if ids == nil then
    --     printError("卡牌id %s 未在 角色羁绊表 找到对应数据", cardId)
    -- end
    return ids
end

