---GetCardMoodByCardIdLevel
---@param cardId number
---@param level number
function CardConfMgr:GetCardMoodByCardIdLevel(cardId, level)
    level = checkNumber(level)
    local ids           = self:GetFavorableExpRewardIdGroup(cardId)
    local cafeEnergy    = 0
    if ids then
        for i, id in ipairs(ids) do
            ---@type FavorableExpRewardVo
            local vo      = self:GetFavorableExpRewardVo(id)
            if vo ~= nil and checkNumber(vo.level) == level then
                cafeEnergy = checkNumber(vo.mood)
                break
            end
        end
    end
    return cafeEnergy
end

