---GetFavorableCardWordVosByCardId
---@param cardId number 卡牌id
function CardConfMgr:GetFavorableCardWordVosByCardId(cardId)
    local ids = self:GetFavorableCardWordIds(cardId)
    if ids == nil then return end
    
    local t
    for i, id in ipairs(ids) do
        t   = t or {}
        table.insert(t, self:GetFavorableCardWordVoById(id))
    end
    return t
    
end

function CardConfMgr:GetFavorableCardWordVoByGroupId(cardId, groupId)
    local ids = self:GetFavorableCardWordIds(cardId)
    if ids == nil then return end
    local t
    for i, id in ipairs(ids) do
        ---@type FavorableCardWordVo
        local vo = self:GetFavorableCardWordVoById(id) 
        for _, groupType in ipairs(vo.groupIds) do
            if groupId == checkNumber(groupType) then
                t   = t or {}
                table.insert(t, vo)
            end
        end
        
    end
    return t
end

