--获取俩张卡组成的特殊羁绊效果id   没有返回0
--targetId 主卡牌id
--fettersCardId 羁绊位置的卡牌id
function CardConfMgr:GetRoleCardSynergiesId(targetId, fettersCardId)
    if checkNumber(fettersCardId) <= 0 then
        return 0
    end
    local t = self:GetRoleCardSynergies(targetId)
    if not t then
        return 0
    end

    for k, id in pairs(t) do
        local vo = self:GetRoleCardSynergiesVo(id)
        if vo then
            if checkNumber(vo.relationCard) == checkNumber(fettersCardId) then
                return vo.relationId
            end
        end

    end
    return 0
end

--羁绊普通加成
function CardConfMgr:GetSynergiesAddNum(cardDojo, isIgnoreGlobal)
    return self:GetSynergiesGeneralAddNum(checkNumber(cardDojo.star), cardDojo.cardId, isIgnoreGlobal)
end

--羁绊普通加成
function CardConfMgr:GetSynergiesGeneralAddNum(star, cardId, isIgnoreGlobal)
    ---@type CardVo
    local cardVo   = self:GetCardByRefId(cardId)
    local initRare = cardVo.rare
    local t        = self:GetSynergiesConf()
    local cardParamConfId     = t[initRare]

    local str = self:GetCardProgressionParamsById(cardParamConfId)
    local t = checkTable(CfUtils.Split(checkString(str)))

    local talentEffectId = Constants.GlobalTalentEffectId.Id_3
    local baseNum = checkNumber(t[star + 1])
    local num = baseNum
    if not isIgnoreGlobal then
        ---@type GlobalTalentMgr
        local instance             = GlobalTalentMgr:GetInstance()
        num = instance:CalcNum(baseNum, talentEffectId, true, function (data)
            --- 羁绊是覆盖逻辑大于 直接算生效
            ---@type HomelandTalentUpLvVo
            local vo = data.vo
            return vo.param1 >= initRare
        end)
    end

    return num

end

function CardConfMgr:GetSynergiesConf()
    if self._synergiesConf == nil then
        self._synergiesConf = {
            [Constants.RareType.SSR] = 32,
            [Constants.RareType.SR]  = 33,
            [Constants.RareType.R]   = 34,
        }
    end
    return self._synergiesConf
end

--俩张卡羁绊的加成
function CardConfMgr:GetFettersAddAttr(cardDojo, fettersCardDojo)
    if not cardDojo or not fettersCardDojo then
        return {}
    end
    ---@type CardProgressionCombatEffUtils
    local CardProgressionCombatEffUtils     = import("Game.CardProgression.CardProgressionCombatEffUtils")
    local attrId2ProviderAttrAddTypeConfig = {}
    attrId2ProviderAttrAddTypeConfig = CardProgressionCombatEffUtils.GenerateSynergiesCombatEffConf(nil, fettersCardDojo, attrId2ProviderAttrAddTypeConfig)

    local attrId2ExtNum = {}
    local AttrTypeId    = Constants.AttrTypeId
    local providerType  = Constants.AttributeProviderType.Synergies
    local ConstType     = Constants.BasicAttrAddType.Const
    local t             = {AttrTypeId.Attack, AttrTypeId.Defense, AttrTypeId.Hp}
    for index, attrId in pairs(t) do
        local providerAttrAddTypeConfig = attrId2ProviderAttrAddTypeConfig[attrId]
        local attrAddTypeConfig = providerAttrAddTypeConfig[providerType]
        if attrAddTypeConfig then
            attrId2ExtNum[attrId] = attrAddTypeConfig[ConstType] or 0
        end
    end

    return attrId2ExtNum
    
end

